<style>
    :root{--bg:#071014;--panel:#0f1c22;--line:rgba(24,199,255,.18);--text:#f7fbfc;--muted:#94aeb5;--orange:#ff8b32;--cyan:#18c7ff;--green:#20e6a4}*{box-sizing:border-box}body{margin:0;color:var(--text);background:radial-gradient(circle at 12% 3%,rgba(255,122,26,.18),transparent 32rem),radial-gradient(circle at 88% 5%,rgba(24,199,255,.12),transparent 28rem),var(--bg);font:15px/1.7 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}.resource-wrap{width:min(1120px,calc(100% - 36px));margin:0 auto}.resource-hero{padding:76px 0 46px}.resource-eyebrow{display:inline-flex;padding:6px 10px;border:1px solid rgba(255,139,50,.3);border-radius:999px;color:#ffb377;background:rgba(255,139,50,.08);font-size:11px;font-weight:800;letter-spacing:.09em;text-transform:uppercase}.resource-hero h1{max-width:880px;margin:18px 0 16px;font-size:clamp(38px,6vw,68px);line-height:1.02}.resource-lead{max-width:790px;margin:0;color:#bfd0d7;font-size:18px}.resource-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;padding-bottom:62px}.resource-card,.article-section,.resource-cta,.faq-item{border:1px solid var(--line);border-radius:14px;background:linear-gradient(145deg,rgba(255,255,255,.055),rgba(24,199,255,.025))}.resource-card{display:flex;flex-direction:column;padding:23px}.resource-card small{color:var(--orange);font-weight:800;text-transform:uppercase;letter-spacing:.07em}.resource-card h2{margin:10px 0 9px;font-size:22px;line-height:1.2}.resource-card p{margin:0 0 20px;color:var(--muted)}.resource-card a{margin-top:auto;color:var(--cyan);font-weight:800}.article-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:22px;align-items:start;padding-bottom:30px}.article-main{display:grid;gap:18px}.article-section{padding:26px}.article-section h2{margin:0 0 12px;font-size:28px;line-height:1.18}.article-section p{margin:0 0 13px;color:#bfd0d7}.article-section p:last-child{margin-bottom:0}.checklist{display:grid;gap:8px;margin:18px 0 0;padding:0;list-style:none}.checklist li{position:relative;padding-left:25px;color:#dce9ed}.checklist li:before{content:"✓";position:absolute;left:0;color:var(--green);font-weight:900}.article-aside{position:sticky;top:84px;display:grid;gap:12px}.aside-card{padding:18px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.035)}.aside-card strong{display:block;margin-bottom:8px}.aside-card a{display:block;padding:5px 0;color:var(--cyan);font-size:13px}.faq-list{display:grid;gap:12px;padding-bottom:28px}.faq-item{padding:20px}.faq-item h3{margin:0 0 7px}.faq-item p{margin:0;color:var(--muted)}.resource-cta{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:28px 0 10px;padding:28px}.resource-cta h2{margin:0 0 6px}.resource-cta p{margin:0;color:var(--muted)}.resource-button{display:inline-flex;min-height:42px;align-items:center;justify-content:center;padding:10px 17px;border-radius:8px;color:#fff;background:linear-gradient(115deg,#ff4c00,#bf4911 42%,#12a5ba 74%,#11a5bd);font-weight:800;white-space:nowrap}.related{padding:34px 0 12px}.related h2{font-size:28px}.breadcrumb{padding-top:26px;color:var(--muted);font-size:13px}.breadcrumb a{color:var(--cyan)}@media(max-width:900px){.resource-grid{grid-template-columns:1fr}.article-layout{grid-template-columns:1fr}.article-aside{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.resource-wrap{width:min(100% - 24px,1120px)}.resource-hero{padding-top:52px}.article-aside{grid-template-columns:1fr}.resource-cta{align-items:flex-start;flex-direction:column}.resource-button{width:100%}}
    .resource-cta{flex-direction:row;justify-content:space-between;text-align:left;margin:28px auto 10px;padding:36px 28px}
    .resource-cta>div{max-width:720px}
    .resource-cta .resource-button{min-width:150px;margin-top:4px}
    @media(max-width:620px){.resource-cta{align-items:flex-start;flex-direction:column;text-align:left;padding:28px 20px}.resource-cta .resource-button{width:min(100%,260px)}}
</style>
